"use client";

import { useState, useRef, useEffect } from "react";
import { Camera, Paperclip, Send, User, Bot, Loader2, ArrowLeft } from "lucide-react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";

type Message = {
  role: "user" | "assistant";
  content: string;
};

export default function ChatPage() {
  const [messages, setMessages] = useState<Message[]>([
    {
      role: "assistant",
      content: "Hi there! I'm your IT support assistant. How can I help you today? Please explain your issue, paste an error message, or upload a screenshot."
    }
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const searchParams = useSearchParams();
  const mode = searchParams.get("mode");

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    if (mode === "photo") {
      setInput("I have a photo of my issue, but image upload is not fully implemented yet in this demo.");
    } else if (mode === "paste") {
      setInput("Here is my error message: ");
    }
  }, [mode]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const newMessages = [...messages, { role: "user" as const, content: input }];
    setMessages(newMessages);
    setInput("");
    setIsLoading(true);

    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: newMessages }),
      });

      if (!response.ok) {
        throw new Error("Failed to get response");
      }

      const reader = response.body?.getReader();
      const decoder = new TextDecoder("utf-8");

      let assistantMessage = "";
      setMessages((prev) => [...prev, { role: "assistant", content: "" }]);

      while (true) {
        const { done, value } = await reader!.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split("\n").filter((line) => line.trim() !== "");

        for (const line of lines) {
          try {
            const data = JSON.parse(line);
            if (data.message?.content) {
              assistantMessage += data.message.content;
              setMessages((prev) => {
                const newMessages = [...prev];
                newMessages[newMessages.length - 1].content = assistantMessage;
                return newMessages;
              });
            }
          } catch (e) {
            console.error("Error parsing JSON:", e);
          }
        }
      }
    } catch (error) {
      console.error(error);
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: "Sorry, I am having trouble connecting to my brain right now. Make sure your local Gemma model is running via Ollama.",
        },
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f1f5f9] flex flex-col font-sans">
      {/* Header */}
      <div className="bg-[#0f172a] text-white p-4 flex items-center shadow-md z-10 sticky top-0">
        <Link href="/" className="mr-4 p-2 hover:bg-slate-800 rounded-full transition-colors">
          <ArrowLeft className="h-5 w-5" />
        </Link>
        <div>
          <h1 className="text-lg font-semibold tracking-tight">IT Support Assistant</h1>
          <p className="text-slate-400 text-xs mt-0.5">Powered by Gemma</p>
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 max-w-3xl w-full mx-auto p-4 overflow-y-auto flex flex-col gap-4 pb-32">
        {messages.map((msg, idx) => (
          <div
            key={idx}
            className={`flex gap-4 ${msg.role === "user" ? "flex-row-reverse" : ""}`}
          >
            <div className={`flex-shrink-0 h-10 w-10 rounded-full flex items-center justify-center ${msg.role === "user" ? "bg-[#38bdf8]" : "bg-slate-200"}`}>
              {msg.role === "user" ? <User className="text-white h-5 w-5" /> : <Bot className="text-slate-600 h-5 w-5" />}
            </div>
            <div className={`p-4 rounded-2xl max-w-[85%] shadow-sm ${msg.role === "user" ? "bg-white border border-gray-100 text-slate-800" : "bg-slate-50 border border-slate-200 text-slate-700"}`}>
              <p className="whitespace-pre-wrap leading-relaxed">{msg.content}</p>
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="fixed bottom-0 left-0 right-0 bg-[#f1f5f9] p-4">
        <div className="max-w-3xl mx-auto">
          <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-sm border border-gray-200 p-2 flex items-end gap-2 focus-within:border-blue-400 focus-within:ring-2 focus-within:ring-blue-100 transition-all">
            <button type="button" className="p-3 text-slate-400 hover:text-slate-600 transition-colors">
              <Camera className="h-5 w-5" />
            </button>
            <button type="button" className="p-3 text-slate-400 hover:text-slate-600 transition-colors">
              <Paperclip className="h-5 w-5" />
            </button>
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  handleSubmit(e);
                }
              }}
              placeholder="Describe your issue or paste an error..."
              className="flex-1 bg-transparent p-3 outline-none resize-none max-h-32 text-slate-700"
              rows={1}
            />
            <button
              type="submit"
              disabled={isLoading || !input.trim()}
              className="p-3 bg-[#0f172a] text-white rounded-xl hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {isLoading ? <Loader2 className="h-5 w-5 animate-spin" /> : <Send className="h-5 w-5" />}
            </button>
          </form>
          <div className="text-center mt-3 text-xs text-slate-400">
            If this takes too long, you can always <Link href="/support" className="text-blue-500 hover:underline">contact a real person</Link>.
          </div>
        </div>
      </div>
    </div>
  );
}
